### TypeScript

Nano ID 允许将生成的字符串转换为 TypeScript 中的不透明字符串。 例如：

```ts
declare const userIdBrand: unique symbol;
type UserId = string & { [userIdBrand]: true };

// 使用显式类型参数:
mockUser(nanoid<UserId>());

interface User {
  id: UserId;
  name: string;
}

const user: User = {
  // 自动转换为 UserId:
  id: nanoid(),
  name: "Alice",
};
```

export function customRandom(alphabet, defaultSize, getRandom) {
  // Random bytes are 0-255. `random % alphabet.length` can waste
  // that entropy by making some symbols more likely.
  //
  // `safeByteCutoff` will be divided by `alphabet.length` without remainder
  // fixing issue of broken distribution.
  //
  // Example: with 17 symbols, `safeByteCutoff` is 255.
  // Bytes 0-254 preserve entropy evenly: each symbol gets 15 source bytes.
  // Byte 255 would map to `0` again, making one symbol slightly more likely.
  // So we reject 255.
  let safeByteCutoff = 256 - (256 % alphabet.length)

  // Power-of-two alphabets can use `& mask` instead of modulo.
  if (safeByteCutoff === 256) {
    let mask = alphabet.length - 1

### 自定义字母或大小

`customAlphabet` 返回一个函数，允许您使用自定义字母表和ID大小创建 `nanoid`。

```js
import { customAlphabet } from "nanoid";
const nanoid = customAlphabet("1234567890abcdef", 10);
model.id = nanoid(); //=> "4f90d13a42"
```

```js
import { customAlphabet } from "nanoid/non-secure";
const nanoid = customAlphabet("1234567890abcdef", 10);
user.id = nanoid();
```

在我们的 [ID 碰撞概率] 计算器中检查您的自定义字母表和 ID 大小的安全性。
查看 [`nanoid-dictionary`] 中的选项以获取更多字母表。

字母表必须包含256个或更少的符号。
否则，无法保证内部生成器算法的安全性。

export let customRandom = (alphabet, defaultSize, getRandom) => {
  // Random bytes are 0-255. `random % alphabet.length` can waste
  // that entropy by making some symbols more likely.
  //
  // `safeByteCutoff` will be divided by `alphabet.length` without remainder
  // fixing issue of broken distribution.
  //
  // Example: with 17 symbols, `safeByteCutoff` is 255.
  // Bytes 0-254 preserve entropy evenly: each symbol gets 15 source bytes.
  // Byte 255 would map to `0` again, making one symbol slightly more likely.
  // So we reject 255.
  let safeByteCutoff = 256 - (256 % alphabet.length)

  // Power-of-two alphabets can use `& mask` instead of modulo.
  if (safeByteCutoff === 256) {
    let mask = alphabet.length - 1

### 自定义随机字节生成器

`customRandom` 允许您创建一个 `nanoid` 并替换字母表
和默认的随机字节生成器。

在此示例中，使用基于种子的生成器:

```js
import { customRandom } from "nanoid";

const rng = seedrandom(seed);
const nanoid = customRandom("abcdef", 10, (size) => {
  return new Uint8Array(size).map(() => 256 * rng());
});

nanoid(); //=> "fbaefaadeb"
```

`random` 回调必须接受数组大小并返回随机数的数组。

如果要使用与 `customRandom` 相同的URL友好符号,
您可以使用 `urlAlphabet` 获取默认字母表。

```js
const { customRandom, urlAlphabet } = require("nanoid");
const nanoid = customRandom(urlAlphabet, 10, random);
```

export let nanoid = (size = 21) => {
  let id = ''
  let bytes = crypto.getRandomValues(new Uint8Array((size |= 0)))
  while (size--) {
    // The following mask reduces the random byte in the 0-255 value
    // range to the 0-63 value range.
    id += urlAlphabet[bytes[size] & 63]
  }
  return id
}

export function customAlphabet(alphabet, defaultSize = 21) {
  if (
    typeof alphabet !== 'string' ||
    !alphabet ||
    alphabet.length > 256
  ) {
    return customRandom(alphabet, defaultSize, random)
  }
  for (let i = 0; i < alphabet.length; i++) {
    if (alphabet.charCodeAt(i) > 255) {
      // The fast path below writes char codes to a byte buffer,
      // so it supports only single-byte characters.
      return customRandom(alphabet, defaultSize, random)
    }
  }

test(`supports power-of-two alphabets`, () => {
  let sequence = [2, 255, 3, 7]
  function fakeRandom(size) {
    let bytes = []
    for (let i = 0; i < size; i += sequence.length) {
      bytes = bytes.concat(sequence.slice(0, size - i))
    }
    return bytes
  }
  let nanoid4 = customRandom('abcd', 4, fakeRandom)
  equal(nanoid4(), 'dddc')
  equal(nanoid4(0), '')
})

test(`supports generator`, () => {
  let sequence = [2, 255, 3, 7, 7, 7, 7, 7, 0, 1]
  function fakeRandom(size) {
    let bytes = []
    for (let i = 0; i < size; i += sequence.length) {
      bytes = bytes.concat(sequence.slice(0, size - i))
    }
    return bytes
  }
  let nanoid4 = customRandom('abcde', 4, fakeRandom)
  let nanoid18 = customRandom('abcde', 18, fakeRandom)
  equal(nanoid4(), 'cccc')
  equal(nanoid18(), 'acccccdcbacccccdcb')
})

describe('random', () => {
  test(`throws on negative size`, () => {
    throws(() => {
      random(-1)
    }, /Wrong ID size|Invalid typed array length/)
  })

  test(`generates small random buffers`, () => {
    for (let i = 0; i < urlAlphabet.length; i++) {
      equal(random(10).length, 10)
    }
  })

  test(`generates random buffers`, () => {
    let numbers = {}
    let bytes = random(1000)
    equal(bytes.length, 1000)
    for (let byte of bytes) {
      if (!numbers[byte]) numbers[byte] = 0
      numbers[byte] += 1
      equal(typeof byte, 'number')
      ok(byte <= 255)
      ok(byte >= 0)
    }
  })
})
